  runKv.title = r.runId || "";
  box.appendChild(runKv);
  box.appendChild(kv("in", fmtTok(t.inputTokens)));
  box.appendChild(kv("out", fmtTok(t.outputTokens)));
  box.appendChild(kv("cache", fmtTok(t.cacheReadTokens) + "r " + fmtTok(t.cacheWriteTokens) + "w"));
