  showFeed(false);
  renderAggregate();
  fetch("/api/runs").then(function (res) {
    if (!res.ok) throw new Error("http " + res.status);
    return res.json();
  }).then(function (data) {
    runs = (data && data.records) || [];
    renderRuns();
    renderAggregate();
    if (!selectedId && runs.length) selectRun(sortedRuns()[0].runId);
  }).catch(function () {
    var list = $("runlist");
    list.textContent = "";
    list.appendChild(el("div", "list-empty", "failed to load runs (/api/runs)"));
  });
